public List<List<String>> accountsMerge(List<List<String>> accounts) {
    Map<String, Integer> emailToId = new HashMap<>();
    Map<String, String> emailToName = new HashMap<>();
    int id = 0;
    for (List<String> acc : accounts)
        for (int i = 1; i < acc.size(); i++) {
            String email = acc.get(i);
            if (!emailToId.containsKey(email)) emailToId.put(email, id++);
            emailToName.put(email, acc.get(0));
        }
    DSU dsu = new DSU(id);
    for (List<String> acc : accounts)
        for (int i = 2; i < acc.size(); i++)
            dsu.union(emailToId.get(acc.get(1)), emailToId.get(acc.get(i)));

    Map<Integer, TreeSet<String>> groups = new HashMap<>();
    for (Map.Entry<String, Integer> e : emailToId.entrySet()) {
        int root = dsu.find(e.getValue());
        groups.computeIfAbsent(root, z -> new TreeSet<>()).add(e.getKey());
    }
    List<List<String>> res = new ArrayList<>();
    for (TreeSet<String> emails : groups.values()) {
        List<String> row = new ArrayList<>();
        row.add(emailToName.get(emails.first()));
        row.addAll(emails);
        res.add(row);
    }
    return res;
}

