public String smallestStringWithSwaps(String s, List<List<Integer>> pairs) {
    int n = s.length();
    DSU dsu = new DSU(n);
    for (List<Integer> p : pairs) dsu.union(p.get(0), p.get(1));

    Map<Integer, List<Integer>> comp = new HashMap<>();
    for (int i = 0; i < n; i++)
        comp.computeIfAbsent(dsu.find(i), z -> new ArrayList<>()).add(i); // ascending i

    char[] res = s.toCharArray();
    for (List<Integer> idxs : comp.values()) {
        char[] chars = new char[idxs.size()];
        for (int i = 0; i < idxs.size(); i++) chars[i] = s.charAt(idxs.get(i));
        Arrays.sort(chars);
        for (int i = 0; i < idxs.size(); i++) res[idxs.get(i)] = chars[i];
    }
    return new String(res);
}

