public int numberOfGoodPaths(int[] vals, int[][] edges) {
    int n = vals.length;
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }

    TreeMap<Integer, List<Integer>> byVal = new TreeMap<>();
    for (int i = 0; i < n; i++)
        byVal.computeIfAbsent(vals[i], z -> new ArrayList<>()).add(i);

    DSU dsu = new DSU(n);
    int good = n; // each node is a good path by itself
    for (Map.Entry<Integer, List<Integer>> e : byVal.entrySet()) {
        int v = e.getKey();
        for (int u : e.getValue())
            for (int w : adj.get(u))
                if (vals[w] <= v) dsu.union(u, w);
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int u : e.getValue()) {
            int root = dsu.find(u);
            int c = cnt.getOrDefault(root, 0);
            good += c;            // pair u with the c earlier same-value nodes in its component
            cnt.put(root, c + 1);
        }
    }
    return good;
}

