public int largestIsland(int[][] grid) {
    int n = grid.length;
    DSU dsu = new DSU(n * n);
    int[][] down = {{0, 1}, {1, 0}};
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++)
            if (grid[r][c] == 1)
                for (int[] d : down) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr < n && nc < n && grid[nr][nc] == 1)
                        dsu.union(r * n + c, nr * n + nc);
                }

    int best = 0;
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++)
            if (grid[r][c] == 1) best = Math.max(best, dsu.size(dsu.find(r * n + c)));

    int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++)
            if (grid[r][c] == 0) {
                Set<Integer> roots = new HashSet<>();
                int total = 1;
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nc >= 0 && nr < n && nc < n && grid[nr][nc] == 1) {
                        int root = dsu.find(nr * n + nc);
                        if (roots.add(root)) total += dsu.size(root);
                    }
                }
                best = Math.max(best, total);
            }
    return best; // all-ones -> n*n; all-zeros -> 1 from the zero loop
}

class DSU {
    int[] p, sz;
    DSU(int n) { p = new int[n]; sz = new int[n]; for (int i = 0; i < n; i++) { p[i] = i; sz[i] = 1; } }
    int find(int x) { while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; } return x; }
    void union(int a, int b) { int ra = find(a), rb = find(b); if (ra != rb) { p[ra] = rb; sz[rb] += sz[ra]; } }
    int size(int root) { return sz[root]; }
}
